import java.util.Scanner;
public class VendingMachine1
{
	public static void main(String[] args)
	{
		//Khatwa 1: Tareef al-thawabet allati nahtajuha li hadha al-barnamaj
		final int PENNIES_PER_DOLLAR = 100;
		final int PENNIES_PER_QUARTER = 25;
		//Khatwa 2: Qiraat qimat al-fatora wa si'r al-muntaj
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil qimat al-waraqa bi-dolaar (1 = $1 waraqa, 5 = $5 waraqa, etc.): ");
		int billValue = scan.nextInt();
		System.out.println("Adkhil si'r al-muntaj bil-santimat: ");
		int itemPrice = scan.nextInt();
		scan.close();
		//Khatwa 3: Hisab al-baqi al-mustahaq
		int changeDue = PENNIES_PER_DOLLAR * billValue - itemPrice;
		//Khatwa 4: Hisab adad al-dolarat wa tahdith al-baqi ba'da isqat al-dolarat
		int dollars = changeDue / PENNIES_PER_DOLLAR;
		changeDue = changeDue % PENNIES_PER_DOLLAR;
		//Khatwa 5: Hisab adad al-arba'at fi al-baqi al-mutabaqi
		int quarters = changeDue / PENNIES_PER_QUARTER;
		//Khatwa 6: Ard al-nateejah
		System.out.println("Al-baqi yatakawan min:"); 
		System.out.println(dollars + " dolarat");
		System.out.println(quarters + " arbaat");
	}
}
